import UIKit

class ViewController: UIViewController {

    override func viewDidLoad() {
        super.viewDidLoad()
        // Do any additional setup after loading the view, typically from a nib.
    }

    override func didReceiveMemoryWarning() {
        super.didReceiveMemoryWarning()
        // Dispose of any resources that can be recreated.
    }

    @IBAction func buttonPressed(_ sender: UIButton) {
        // Create a new ActivityIndicatorView
        let indicatorView = ActivityIndicatorView(frame: CGRect(x: 100, y: 100, width: 100, height: 100))

        // Add it to the view
        view.addSubview(indicatorView)

        // Start the animation
        indicatorView.startAnimating()

        // After 5 seconds, stop the animation
        DispatchQueue.main.asyncAfter(deadline:.now() + 5) {
            indicatorView.stopAnimating()
        }
    }
}

// ActivityIndicatorView is a custom view that displays an activity indicator
class ActivityIndicatorView: UIView {

    // The activity indicator
    var indicator: UIActivityIndicatorView!

    override init(frame: CGRect) {
        super.init(frame: frame)
        setup()
    }

    required init?(coder aDecoder: NSCoder) {
        super.init(coder: aDecoder)
        setup()
    }

    // Set up the view
    func setup() {
        // Create the activity indicator
        indicator = UIActivityIndicatorView(activityIndicatorStyle:.gray)
        indicator.center = CGPoint(x: frame.width / 2, y: frame.height / 2)
        indicator.hidesWhenStopped = true
        addSubview(indicator)
    }

    // Start the animation
    func startAnimating() {
        indicator.startAnimating()
    }

    // Stop the animation
    func stopAnimating() {
        indicator.stopAnimating()
    }
}
```
